        <g transform="translate(80 60) rotate(40)"><path class="petal p2" d="M 0 0 C 2.6 -1.2, 3.8 -3.4, 3 -5.8 C 0.8 -5, -0.8 -2.6, 0 0 Z" fill="var(--koi-pad-line)" opacity=".4"/></g>
