let inkWaterInstance = 0;
const activeInkWater = new WeakMap();
const clampKoi = (value, min, max) => Math.min(max, Math.max(min, value));

function varify(svg) {
  svg.querySelectorAll("*").forEach((element) => {
    for (const attr of [...element.attributes]) {
      if (attr.name !== "style" && attr.name !== "class" && attr.value.includes("var(")) {
        element.style.setProperty(attr.name, attr.value);
        element.removeAttribute(attr.name);
      }
    }
  });
}

function nowFor(svg) {
  return svg.ownerDocument?.defaultView?.performance?.now?.() ?? Date.now();
}

function chooseKoiTarget(koi, now, awayFrom = null) {
  const heading = Math.atan2(koi.vy, koi.vx) || 0;
  const escapeHeading = awayFrom ? Math.atan2(koi.y - awayFrom.y, koi.x - awayFrom.x) : heading;
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const spread = awayFrom ? .8 : 1.35;
    const angle = escapeHeading + (Math.random() - .5) * spread * Math.PI;
    const distance = 16 + Math.random() * 17;
    const x = koi.x + Math.cos(angle) * distance;
    const y = koi.y + Math.sin(angle) * distance;
    if (Math.hypot(x - 64, y - 64) < 31) {
      koi.target = { x, y };
      koi.nextTurnAt = now + 1050 + Math.random() * 1800;
      return;
    }
  }
  koi.target = { x: 64 + (Math.random() - .5) * 28, y: 64 + (Math.random() - .5) * 28 };
  koi.nextTurnAt = now + 900 + Math.random() * 1200;
}

function renderKoiSchool(controller) {
  for (const koi of controller.fish) {
    const heading = Math.atan2(koi.vy, koi.vx) * 180 / Math.PI;
    koi.node.setAttribute("transform", `translate(${koi.x.toFixed(2)} ${koi.y.toFixed(2)}) rotate(${heading.toFixed(2)}) scale(${koi.scale})`);
  }
}

function startleKoiSchool(controller) {
  if (controller.svg.classList.contains("koi-startled")) return;
  controller.svg.classList.add("koi-startled");
  if (controller.startleTimer) controller.window.clearTimeout(controller.startleTimer);
  controller.startleTimer = controller.window.setTimeout(() => {
    controller.svg.classList.remove("koi-startled");
    controller.startleTimer = null;
  }, 280);
}

function advanceKoiSchool(controller, elapsed, time) {
  const current = nowFor(controller.svg);
  const pointer = controller.pointer?.expiresAt > current ? controller.pointer : null;
  if (!pointer) controller.pointer = null;
  const now = time * 1000;
  let startled = false;

  for (const koi of controller.fish) {
    let isFleeing = false;
    if (pointer) {
      const dx = koi.x - pointer.x;
      const dy = koi.y - pointer.y;
      const distance = Math.hypot(dx, dy) || .01;
      if (distance < 27) {
        const force = (1 - distance / 27) * 340;
        koi.vx += dx / distance * force * elapsed;
        koi.vy += dy / distance * force * elapsed;
        if (now >= koi.fleeUntil) {
          chooseKoiTarget(koi, now, pointer);
          koi.fleeUntil = now + 440;
        }
        isFleeing = true;
        startled = true;
      }
    }

    let targetDx = koi.target.x - koi.x;
    let targetDy = koi.target.y - koi.y;
    let targetDistance = Math.hypot(targetDx, targetDy) || 1;
    if (!isFleeing && (now >= koi.nextTurnAt || targetDistance < 6)) {
      chooseKoiTarget(koi, now);
      targetDx = koi.target.x - koi.x;
      targetDy = koi.target.y - koi.y;
      targetDistance = Math.hypot(targetDx, targetDy) || 1;
    }
    const steer = isFleeing ? 10 : 18;
    koi.vx += targetDx / targetDistance * steer * elapsed;
    koi.vy += targetDy / targetDistance * steer * elapsed;
    koi.vx += Math.sin(time * 1.7 + koi.phase) * 1.25 * elapsed;
    koi.vy += Math.cos(time * 1.19 + koi.phase) * .95 * elapsed;

    const speed = Math.hypot(koi.vx, koi.vy) || 1;
    const maximumSpeed = isFleeing ? 49 : 13.2;
    if (speed > maximumSpeed) {
      koi.vx = koi.vx / speed * maximumSpeed;
      koi.vy = koi.vy / speed * maximumSpeed;
    }
    koi.vx *= isFleeing ? .991 : .976;
    koi.vy *= isFleeing ? .991 : .976;
    koi.x += koi.vx * elapsed;
    koi.y += koi.vy * elapsed;

    const dx = koi.x - 64;
    const dy = koi.y - 64;
    const distance = Math.hypot(dx, dy) || 1;
    const pondEdge = 36 - koi.scale * 3;
    if (distance > pondEdge) {
      const nx = dx / distance;
      const ny = dy / distance;
      koi.x = 64 + nx * pondEdge;
      koi.y = 64 + ny * pondEdge;
      const outwardSpeed = koi.vx * nx + koi.vy * ny;
      if (outwardSpeed > 0) {
        koi.vx -= nx * outwardSpeed * 1.92;
        koi.vy -= ny * outwardSpeed * 1.92;
      }
      chooseKoiTarget(koi, now, { x: 64 + nx * 50, y: 64 + ny * 50 });
    }
  }

  for (let index = 0; index < controller.fish.length; index += 1) {
    for (let otherIndex = index + 1; otherIndex < controller.fish.length; otherIndex += 1) {
      const first = controller.fish[index];
      const second = controller.fish[otherIndex];
      const dx = first.x - second.x;
      const dy = first.y - second.y;
      const distance = Math.hypot(dx, dy) || .01;
      if (distance < 15) {
        const push = (1 - distance / 15) * 7.5 * elapsed;
        first.vx += dx / distance * push;
        first.vy += dy / distance * push;
        second.vx -= dx / distance * push;
        second.vy -= dy / distance * push;
      }
    }
  }
  if (startled) startleKoiSchool(controller);
}

function mountKoiSchool(svg) {
  const nodes = [...svg.querySelectorAll("[data-inside-koi]")];
  const windowRef = svg.ownerDocument.defaultView || globalThis;
  const starts = [
    { x: 51, y: 51, vx: 10.2, vy: -6.1, scale: .76, phase: .4, target: { x: 76, y: 43 } },
    { x: 77, y: 69, vx: -8.6, vy: 5.8, scale: .61, phase: 2.3, target: { x: 48, y: 78 } },
    { x: 55, y: 84, vx: 6.7, vy: 8.4, scale: .48, phase: 4.7, target: { x: 77, y: 73 } }
  ];
  const now = nowFor(svg);
  const controller = {
    svg,
    window: windowRef,
    fish: nodes.map((node, index) => ({ ...starts[index], node, nextTurnAt: now + 900 + index * 520, fleeUntil: 0 })),
    pointer: null,
    startleTimer: null
  };
  controller.readPointer = (event) => {
    const rect = svg.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    controller.pointer = {
      x: clampKoi((event.clientX - rect.left) / rect.width * 128, 0, 128),
      y: clampKoi((event.clientY - rect.top) / rect.height * 128, 0, 128),
      expiresAt: nowFor(svg) + 190
    };
  };
  controller.clearPointer = () => { controller.pointer = null; };
  svg.addEventListener("pointermove", controller.readPointer);
  svg.addEventListener("pointerleave", controller.clearPointer);
  renderKoiSchool(controller);
  return controller;
}

function createInkWaterElement(documentRef) {
  const element = documentRef.createElement("span");
  element.className = "translation-orb__ink-water";
  element.innerHTML = inkSVG(`ink-water-${++inkWaterInstance}`);
  const svg = element.firstElementChild;
  varify(svg);
  const controller = mountKoiSchool(svg);
  const windowRef = documentRef.defaultView || globalThis;
  let raf = 0;
  let lastFrame = nowFor(svg);
  let wasConnected = false;
  let destroyed = false;

  const reduced = () => windowRef.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  const frame = (now) => {
    if (destroyed) return;
    if (svg.isConnected) {
      wasConnected = true;
      const elapsed = Math.min(.05, Math.max(0, (now - lastFrame) / 1000));
      lastFrame = now;
      if (!reduced() && element.parentElement?.dataset.skin === "ink-wash") {
        advanceKoiSchool(controller, elapsed, now / 1000);
        renderKoiSchool(controller);
      }
    } else if (wasConnected) {
      destroy();
      return;
    }
    raf = windowRef.requestAnimationFrame(frame);
  };

  const destroy = () => {
    if (destroyed) return;
    destroyed = true;
    if (raf) windowRef.cancelAnimationFrame(raf);
    if (controller.startleTimer) windowRef.clearTimeout(controller.startleTimer);
    svg.removeEventListener("pointermove", controller.readPointer);
    svg.removeEventListener("pointerleave", controller.clearPointer);
    activeInkWater.delete(element);
  };

  activeInkWater.set(element, destroy);
  raf = windowRef.requestAnimationFrame(frame);
  return element;
}

function destroyInkWaterElement(element) {
  activeInkWater.get(element)?.();
}

module.exports = { createInkWaterElement, destroyInkWaterElement };
